pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _logger, bool _status) public {
        // Assume we are the owner (since onlyOwner modifier requires it)
        vm.assume(_logger != address(0));

        // Before calling setApprovedLogger, record the expected value
        // In the reference, after the call with _status, approvedLoggers[_logger] should become _status
        // In the mutant, it remains unchanged (false).
        // So after the call, we check: approvedLoggers(_logger) == _status for reference,
        // but for mutant it will be false.
        c.setApprovedLogger(_logger, _status);

        // The general rule: after calling setApprovedLogger with (_logger, _status),
        // the value returned by approvedLoggers(_logger) should equal _status.
        assertTrue(c.approvedToLog(_logger) == _status);
    }
}

