pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _logger, bool _status) public {
        // Restrict inputs: _logger can be any address (including zero), _status any bool
        // Only the owner can call setApprovedLogger; we need to impersonate the owner.
        // The owner is the one who deployed the contract (this test contract).
        // But since the contract has no explicit owner set, _contractOwner is uninitialized (address(0)).
        // So only address(0) can call onlyOwner functions. We must use vm.prank(address(0)).
        vm.assume(_logger != address(0)); // avoid trivial cases where logger is the zero address
        vm.prank(address(0));
        c.setApprovedLogger(_logger, _status);
        // After the call, the mapping should have been updated to _status.
        assertTrue(c.approvedToLog(_logger) == _status);
    }
}

