pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address logger, bool status) public {
        vm.assume(caller != address(0) && logger != address(0));
        vm.prank(caller);
        // Call setApprovedLogger via the onlyOwner check; but we are not owner, so this reverts.
        // To test the property, we need to be owner. So we set the owner by calling the contract's owner setter if available, but there is none.
        // Instead, we use vm.prank with the owner address; but we don't know it. So we skip this test and provide a simpler property.
        // Actually, the onlyOwner modifier requires msg.sender == _contractOwner, which is private. We cannot set it.
        // So we use a different approach: call setApprovedLogger as any user; it will revert. We can check the revert condition.
        // But the difference is in the assignment: M assigns !status, P assigns status.
        // We can test by checking the return value of approvedToLog after calling setApprovedLogger as owner.
        // Since we cannot call setOwner, we cannot be owner. So we need to change the rule.
        // Let's use vm.assume to only test when caller is the contract owner? But we don't know it.
        // Alternative: we use vm.store to set the owner, but that's not allowed.
        // So we'll test a different property: after a successful setApprovedLogger call (which only owner can do), approvedToLog returns status.
        // But we cannot call setApprovedLogger successfully without being owner. So this test is not feasible.
        // We'll provide a test that calls setApprovedLogger and expects it to revert, and checks that approvedToLog remains false.
        // However, the difference is only in the assignment, not in revert behavior.
        // Let's try: call setApprovedLogger with vm.prank(random), it will revert. Then approvedToLog(logger) should be false (default).
        // Both P and M revert, so the rule holds on both. Not good.
        // Given the constraints, we need a property that P satisfies and M breaks, even with the revert.
        // Since setApprovedLogger reverts for non-owners, the assignment never happens, so the difference is not observable.
        // Thus, the only way is to be owner. But we cannot determine owner. So we must assume we can set it.
        // We can use vm.assume to assume caller is the owner? No, owner is private.
        // So we need another approach: call setApprovedLogger as the contract itself? The owner could be the deployer (address(this) in setUp).
        // In setUp, we deploy with new C(), so the deployer is address(this) (the test contract). So the owner is address(this)!
        // Thus, we can use vm.prank(address(this)) to call setApprovedLogger.
        vm.assume(logger != address(0));
        vm.prank(address(this)); // owner is test contract
        c.setApprovedLogger(logger, status);
        bool result = c.approvedToLog(logger);
        assertTrue(result == status);
    }
}

