pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address logger, bool status) public {
        vm.assume(caller != address(0));
        vm.assume(logger != address(0));
        // Set the approval status for the caller via the logger address (the caller is the caller in the context)
        // We'll use the caller as the msg.sender for setApprovedLogger via prank
        // But the contract has onlyOwner modifier; only the contract owner can call setApprovedLogger.
        // So we assume the caller is the contract owner (first address) for simplicity.
        // Let's use address(1) as a generic caller; we cannot set arbitrary approvals without owner.
        // So to test the rule, we can just set up one approved logger and then call logCreated from that logger.
        // The bug is that logCreated returns false even when approved.
        // We need a simple check: if approvedToLog(msg.sender) is true, then logCreated should return true.
        // Since we cannot change the owner, we'll make a simple test: set a logger as approved, then call logCreated from that logger and check return value equals true.
        // To avoid restrictions, let's use the owner (address(this) because Test is the deployer) as the approved logger.
        c.setApprovedLogger(address(this), true);
        bool ret = c.logCreated(address(0x123));
        assertTrue(ret == true);
    }
}

