pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address _logger, address _keepAddress) public {
        // Ensure the caller is not the zero address to avoid edge cases
        vm.assume(_logger != address(0));

        // Set the caller to _logger
        vm.prank(_logger);

        // Call logCreated and capture the return value
        bool returnedValue = c.logCreated(_keepAddress);

        // Check the rule: the return value must equal approvedToLog(msg.sender) == true
        bool expectedValue = c.approvedToLog(_logger);

        // The reference contract returns false if not approved, true if approved.
        // The mutant always returns true, breaking the rule when approvedToLog returns false.
        assertTrue(returnedValue == expectedValue, "Return value mismatch");
    }
}

